// Üretilen dosya: tool/ozgun/uret.py. Matematik ve Geometri · Türev ve integral uygulamaları: teğet eğimi, ekstremum, maksimum-minimum optimizasyon, eğri altı alan ve değişim hızı (zor).
const ozMathematics19Zor = <(String, String, List<String>, String)>[
  ('A(1, −3) noktasından y = x² parabolüne çizilen iki teğetin eğimleri toplamı kaçtır?', '4', ['−4', '8', '6'], 'Değme noktası t ise −3 = 2t − t² olur, t = 3 veya t = −1 bulunur. Eğimler 6 ve −2 olup toplam 4 tür.'),
  ('f(x) = x³ + ax + b eğrisi A(1, 3) noktasından geçer ve bu noktadaki teğeti y = 2x + 1 doğrusudur. a + b toplamı kaçtır?', '2', ['−2', '4', '5'], 'f\'(1) = 3 + a = 2 ile a = −1 olur. f(1) = 1 − 1 + b = 3 ile b = 3 olur. Toplam 2 dir.'),
  ('Orijinden y = x² + 1 parabolüne çizilen teğetlerin eğimleri aşağıdakilerden hangisidir?', '−2 ve 2', ['−1 ve 1', '−4 ve 4', '0 ve 2'], 'Değme noktası t ise 0 = 2t(0 − t) + t² + 1 olur, t = ±1 bulunur. Eğimler 2t = ±2 dir.'),
  ('y = x² parabolüne x = 1 apsisli noktada çizilen teğete dik olan teğetin değme noktasının apsisi kaçtır?', '−1/4', ['1/4', '−1/2', '−1/8'], 'Birinci teğetin eğimi 2 olduğundan dik teğetin eğimi −1/2 dir. 2x = −1/2 ile x = −1/4 bulunur.'),
  ('f(x) = 4 − x² eğrisine x = 1 apsisli noktada çizilen teğet ile koordinat eksenlerinin sınırladığı üçgenin alanı kaç birimkaredir?', '25/4', ['25/2', '5/4', '25/8'], 'Teğet y = −2x + 5 tir. Kesişimler (5/2, 0) ve (0, 5) tir. Alan (1/2)(5/2)(5) = 25/4 tür.'),
  ('A(2, 0) noktasından y = x³ eğrisine çizilen teğetlerden eğimi sıfırdan farklı olanın eğimi kaçtır?', '27', ['9', '18', '54'], 'Değme noktası t ise 0 = 3t²(2 − t) + t³ olur ve 6t² − 2t³ = 0 ile t = 0 veya t = 3 bulunur. Sıfırdan farklı eğim 3·9 = 27 dir.'),
  ('y = x² parabolüne x = 1 ve x = −3 apsisli noktalarda çizilen teğetlerin kesişim noktası aşağıdakilerden hangisidir?', '(−1, −3)', ['(−1, 3)', '(1, −3)', '(−1, −1)'], 'Teğetler y = 2x − 1 ve y = −6x − 9 dur. Denklemler eşitlenince x = −1 ve y = −3 bulunur.'),
  ('f(x) = (ln x)/x eğrisinin yatay teğetinin değme noktasının apsisi kaçtır?', 'e', ['1', 'e²', '1/e'], 'f\'(x) = (1 − ln x)/x² = 0 ile ln x = 1 yani x = e bulunur.'),
  ('f(x) = x³ + kx + 1 eğrisinin hiçbir teğeti x eksenine paralel olmuyorsa k nın alabileceği değerler aşağıdakilerden hangisidir?', 'k > 0', ['k < 0', 'k ≥ 0', 'k ≤ 0'], '3x² + k = 0 denkleminin gerçek kökü olmamalıdır; bu da k > 0 ile sağlanır.'),
  ('y = 3x² − 6x eğrisi ile x ekseni arasında x = 0 ve x = 3 doğruları arasında kalan toplam alan kaç birimkaredir?', '8', ['0', '4', '12'], '[0, 2] aralığında integral −4, [2, 3] aralığında 4 tür. Alan 4 + 4 = 8 dir.'),
  ('y = x² eğrisi, bu eğriye x = 1 apsisli noktada çizilen teğet ve y ekseni arasında kalan bölgenin alanı kaç birimkaredir?', '1/3', ['1/6', '1/2', '2/3'], 'Teğet y = 2x − 1 dir. ∫ from 0 to 1 of (x² − 2x + 1) dx = ∫ (x − 1)² dx = 1/3 tür.'),
  ('y = sin x ve y = cos x eğrileri ile y ekseni arasında, [0, π/4] aralığında kalan bölgenin alanı kaç birimkaredir?', '√2 − 1', ['√2 + 1', '1 − √2', '2 − √2'], '∫ from 0 to π/4 of (cos x − sin x) dx = [sin x + cos x] ifadesinin 0 dan π/4 e değeri √2 − 1 dir.'),
  ('f çift, g tek fonksiyon; ∫ from 0 to 4 of f(x) dx = 7 ve ∫ from 0 to 4 of g(x) dx = 5 ise ∫ from −4 to 4 of (f(x) + g(x)) dx kaçtır?', '14', ['24', '12', '19'], 'Çift fonksiyon için integral 2·7 = 14, tek fonksiyon için 0 dır. Toplam 14 olur.'),
  ('F(x) = ∫ from 1 to x of (t² + 1) dt ise F\'(2) kaçtır?', '5', ['4', '10', '7/3'], 'Analizin temel teoremine göre F\'(x) = x² + 1 olduğundan F\'(2) = 5 tir.'),
  ('F(x) = ∫ from 0 to x² of (t + 1) dt ise F\'(x) ifadesi aşağıdakilerden hangisidir?', '2x³ + 2x', ['x² + 1', '2x³ + 1', 'x⁴/2 + x²'], 'Zincir kuralıyla F\'(x) = (x² + 1)·2x = 2x³ + 2x olur.'),
  ('f türevlenebilir, f(0) = 3 ve f(2) = 7 ise ∫ from 0 to 2 of f\'(x) dx kaçtır?', '4', ['10', '−4', '21'], 'Analizin temel teoremine göre ∫ f\'(x) dx = f(2) − f(0) = 4 tür.'),
  ('Bir öğrenci y = x³ eğrisi ile x ekseni arasında [−1, 1] aralığında kalan alanı ∫ from −1 to 1 of x³ dx = 0 diye bulmuştur. Bu çözüm için aşağıdakilerden hangisi doğrudur?', 'Hatalıdır; eğri x ekseninin altında da kaldığından iki parçanın mutlak değerleri toplanmalı ve alan 1/2 bulunmalıdır', ['Doğrudur; simetrik aralıklarda her bölgenin alanı 0 olduğu için alan sıfırdır', 'Hatalıdır; alan hesaplanırken yalnızca [0, 1] aralığındaki integral alınmalı ve 1/4 bulunmalıdır', 'Doğrudur; çünkü fonksiyon x = 0 noktasında türevlenebilir ve bu durumda alan 0 olur'], 'İntegral işaretli alanı verir. Gerçek alan 2∫ from 0 to 1 of x³ dx = 1/2 dir.'),
  ('∫ from 0 to 2 of x² dx tam değeri 8/3 iken yamuk kuralı 3 verir. Yamuk kuralının fazla tahmin etmesinin nedeni aşağıdakilerden hangisidir?', 'x² konveks olduğundan yamukların üst kenarları eğrinin üzerinde kalır ve alan fazla bulunur', ['x² fonksiyonu azalan olduğundan yamuklar her zaman eğrinin altında kalır', 'Yamuk kuralı yalnızca çift sayıda alt aralıkta doğru sonuç verdiği için hata oluşur', 'Fonksiyon x ekseninin altında kaldığından yamuk alanları negatif sayılır'], 'Konveks bir fonksiyonda iki uç noktayı birleştiren kiriş eğrinin üstündedir; bu yüzden yamuk toplamı gerçek alandan büyüktür.'),
  ('f(x) = x² fonksiyonunun [0, 3] aralığındaki ortalama değerine eşit olan f(c) değeri için c ∈ (0, 3) değeri kaçtır?', '√3', ['3/2', '3', '9/2'], 'Ortalama değer (1/3)(9) = 3 tür. c² = 3 ile c = √3 bulunur.'),
  ('x > 0 için f(x) = x·ln x fonksiyonunun en küçük değeri kaçtır?', '-1/e', ['-1/e²', '-2/e', '1/e'], 'f\'(x) = ln x + 1 = 0 ise x = 1/e. f(1/e) = (1/e)(−1) = −1/e en küçük değerdir.'),
  ('f(x) = x³ + ax² + bx + c eğrisinin dönüm noktası (1, 2) ve x = 2 apsisli noktada yerel ekstremumu varsa a + b + c kaçtır?', '1', ['4', '2', '-1'], 'f\'\'(1) = 0 ise a = −3. f\'(2) = 12 − 12 + b = 0 ise b = 0. f(1) = 1 − 3 + c = 2 ise c = 4. Toplam 1\'dir.'),
  ('Hacmi 16π cm³ olan kapalı silindir biçimli bir teneke kutunun yüzey alanı en az olacak şekilde yapılırsa bu yüzey alanı kaç cm² olur?', '24π cm²', ['32π cm²', '40π cm²', '48π cm²'], 'S = 2πr² + 32π/r, S\' = 4πr − 32π/r² = 0 ise r = 2, h = 4. S = 8π + 16π = 24π cm² olur.'),
  ('Yarıçapı 6 cm olan bir çembere çizilebilecek dikdörtgenlerin alanı en çok kaç cm² olur?', '72', ['144', '108', '36'], 'Dikdörtgenin köşegeni çapa (12 cm) eşittir. Alan x·√(144 − x²) ifadesinin en büyüğü x = 6√2 için olur; bu bir karedir ve alan 72\'dir.'),
  ('Çevresi 24 cm olan bir dikdörtgen, kenarlarından biri etrafında 360° döndürülüyor. Oluşan silindirin hacmi en çok kaç cm³ olabilir?', '256π cm³', ['288π cm³', '216π cm³', '144π cm³'], 'Dönme ekseni olan kenar x ise yarıçap 12 − x\'tir. V = πx(12 − x)², V\' = π(12 − x)(12 − 3x) = 0 ise x = 4. V = π·4·64 = 256π cm³.'),
  ('Tabanının kenar uzunlukları oranı 1:2 olan dikdörtgenler prizması biçimli kapalı bir kutunun hacmi 72 cm³\'tür. Kutunun yüzey alanı en az kaç cm² olabilir?', '108 cm²', ['144 cm²', '120 cm²', '96 cm²'], 'Taban x ve 2x, yükseklik h = 36/x². S = 4x² + 6xh = 4x² + 216/x, S\' = 8x − 216/x² = 0 ise x = 3. S = 36 + 72 = 108 cm².'),
  ('y = x² parabolü üzerindeki noktaların A(0, 3) noktasına olan uzaklığının en küçük değeri kaç birimdir?', '√11/2', ['√3/2', '√5/2', '3/2'], 'd² = x² + (x² − 3)² = x⁴ − 5x² + 9. Türev 4x³ − 10x = 0 ise x² = 5/2 ve d² = 25/4 − 25/2 + 9 = 11/4; d = √11/2.'),
  ('Taban yarıçapı 6 cm, yüksekliği 9 cm olan bir dik koninin içine tabanı koninin tabanı üzerinde olacak şekilde dik silindir yerleştiriliyor. Silindirin hacmi en çok kaç cm³ olabilir?', '48π', ['36π', '54π', '72π'], 'Silindir yarıçapı r ise yüksekliği h = 9 − 1,5r. V = π(9r² − 1,5r³), V\' = π(18r − 4,5r²) = 0 ise r = 4, h = 3 ve V = 48π.'),
  ('Doğrusal bir yolda hareket eden aracın konumu s(t) = t³ − 9t² + 24t (metre) ile veriliyor. Araç ilk 5 saniyede toplam kaç metre yol alır?', '28 m', ['20 m', '36 m', '40 m'], 'v = 3(t − 2)(t − 4). s(0) = 0, s(2) = 20, s(4) = 16, s(5) = 20. Yol: 20 + 4 + 4 = 28 m (yer değiştirme ise 20 m\'dir).'),
  ('Boyu 1,8 m olan bir kişi, yerden 5,4 m yüksekliğindeki bir lambanın doğrudan altından 3 m/s hızla düz bir yolda uzaklaşıyor. Gölgesinin ucu lamba direğinden saniyede kaç metre uzaklaşır?', '4,5 m/s', ['6,5 m/s', '3,5 m/s', '5,4 m/s'], 'Kişi x, gölge ucu z uzaklıkta ise z/5,4 = (z − x)/1,8 olur ve z = 1,5x. Buradan z\' = 1,5·3 = 4,5 m/s bulunur.'),
  ('Tepe noktası aşağıda, üst taban yarıçapı 2 m ve yüksekliği 4 m olan koni biçimli bir depoya dakikada 3 m³ su dolduruluyor. Su derinliği 2 m iken derinlik dakikada kaç metre artar?', '3/π m/dk', ['3π m/dk', '6/π m/dk', 'π/3 m/dk'], 'Su yüzeyi yarıçapı r = h/2 olduğundan V = πh³/12 ve dV/dt = (πh²/4)·dh/dt. h = 2 için 3 = π·dh/dt ve dh/dt = 3/π m/dk.'),
  ('Kenar uzunluğu 12 cm olan kare şeklindeki bir kartonun dört köşesinden eşit kareler kesilip kenarlar yukarı kıvrılarak üstü açık kutu yapılıyor. Kutunun hacmi en çok kaç cm³ olur?', '128', ['144 cm³', '108 cm³', '162 cm³'], 'Kesilen kare kenarı x ise V(x) = x(12 - 2x)²; V\'(x) = (12 - 2x)(12 - 6x) = 0 ⇒ x = 2; V(2) = 2·8² = 128 cm³ bulunur.'),
  ('y = 12 - x² parabolü ile x ekseni arasına, bir kenarı x ekseni üzerinde ve diğer iki köşesi parabol üzerinde olacak şekilde çizilebilecek en büyük alanlı dikdörtgenin alanı kaç birimkaredir?', '32', ['24 birimkare', '48 birimkare', '36 birimkare'], 'Köşeler (±x, 12 - x²) ise A(x) = 2x(12 - x²) = 24x - 2x³; A\'(x) = 24 - 6x² = 0 ⇒ x = 2; A(2) = 4·8 = 32 birimkaredir.'),
  ('Yarıçapı 6 cm olan bir kürenin içine yerleştirilebilecek en büyük hacimli dik dairesel silindirin yüksekliği kaç cm olur?', '4√3', ['6√2 cm', '6√3 cm', '3√3 cm'], 'Silindir yarıçapı r, yüksekliği h ise r² = 36 - h²/4; V(h) = π(36h - h³/4); V\'(h) = π(36 - 3h²/4) = 0 ⇒ h² = 48 ⇒ h = 4√3 cm\'dir.'),
  ('5 metre uzunluğundaki bir merdiven dik bir duvara yaslıdır. Alt ucu duvardan 3 m uzaktayken 2 m/s hızla dışarı doğru kayıyorsa üst ucu hangi hızla aşağı kayar?', '1,5 m/s', ['2,5 m/s hız', '1,2 m/s hız', '3,0 m/s hız'], 'x² + y² = 25 ve x = 3 iken y = 4; 2x(dx/dt) + 2y(dy/dt) = 0 ⇒ 3·2 + 4·(dy/dt) = 0 ⇒ dy/dt = -1,5 m/s, aşağı hızı 1,5 m/s\'dir.'),
  ('f(x) = x³ - 3kx² + 3x + 5 fonksiyonunun iki farklı yerel ekstremum noktasına sahip olabilmesi için k hangi aralıkta olmalıdır?', '(-∞, -1) ∪', ['(-1, 1) açık aralığı', '(-2, 2) açık aralığı', '[1, +∞) yarı açık aralığı'], 'f\'(x) = 3x² - 6kx + 3 = 0 denkleminin iki farklı gerçek kökü için Δ = 36k² - 36 > 0 ⇒ k² > 1 ⇒ |k| > 1 olmalıdır.'),
  ('Taban yarıçapı R = 4 cm ve yüksekliği H = 12 cm olan ters duran dik dairesel koniye saniyede 2π cm³ su akmaktadır. Su yüksekliği h = 6 cm olduğunda yüksekliğin artış hızı kaç cm/s\'dir?', '1/2', ['1/4 cm/s hız', '1 cm/s hız', '2/3 cm/s hız'], 'r/h = 4/12 = 1/3 ⇒ V = (π/27)h³ ⇒ dV/dt = (π/9)h²(dh/dt); 2π = (π/9)·36·(dh/dt) ⇒ dh/dt = 1/2 cm/s\'dir.'),
  ('G(x) = ∫ₓ^(2x) (1/t) dt (x > 0) fonksiyonunun türevi G\'(x) aşağıdakilerden hangisine eşittir?', '0', ['1/x kesri', 'ln(2) değeri', '2/x kesri'], 'G\'(x) = (1/(2x))·2 - (1/x)·1 = 1/x - 1/x = 0 olur; nitekim G(x) = ln(2x) - ln(x) = ln(2) sabit fonksiyondur.'),
  ('İntegral ile eğri altı alan hesaplanırken f(x) fonksiyonu [a, b] aralığında yer yer negatif değerler alıyorsa gerçek toplam alanı bulmak için nasıl işlem yapılmalıdır?', 'Mutlak değer integrali alınır', ['Doğrudan f(x) integrali alınır', 'Sadece uç noktalar farkı alınır', 'Türevinin integrali hesaplanır'], 'x ekseninin altındaki parçalar belirli integrale negatif katkı yaptığından geometrik alan ∫ₐᵇ |f(x)| dx ile bulunur.'),
  ('y = 1/x eğrisi (x > 0) üzerinde orijine en yakın noktanın orijine uzaklığı kaç birimdir?', '√2', ['2 tam sayısı', '1 tam sayısı', '2√2 değeri'], 'D(x) = x² + 1/x²; D\'(x) = 2x - 2/x³ = 0 ⇒ x = 1 ve y = 1; orijine uzaklık √(1² + 1²) = √2 birimdir.'),
  ('Kuzey-güney ve doğu-batı yönünde dik kesişen bir kavşaktan bir araç kuzeye 60 km/sa, diğer araç doğuya 80 km/sa hızla aynı anda ayrılıyor. İki araç arasındaki uzaklık saatte kaç km artmaktadır?', '100', ['140 km/sa hız', '70 km/sa hız', '120 km/sa hız'], 't saatte x = 80t, y = 60t olduğundan s(t) = √((80t)² + (60t)²) = 100t; ds/dt = 100 km/sa\'tir.'),
  ('Bir firma x adet ürünün toplam maliyetini C(x) = 2x² + 40x + 1800 TL olarak hesaplıyor. Birim başına ortalama maliyeti en düşük yapan üretim adedi kaçtır?', '30', ['40 adet ürün', '20 adet ürün', '45 adet ürün'], 'Ortalama maliyet A(x) = 2x + 40 + 1800/x; A\'(x) = 2 - 1800/x² = 0 ⇒ x² = 900 ⇒ x = 30 adet üründür.'),
  ('y = x² parabolü ile x = 0 ve x = 2 aralığında kalan bölgenin alanını iki eşit parçaya bölen x = k düşey doğrusunun k değeri kaçtır?', '∛4', ['√2 değeri', '1 tam sayısı', '∛2 değeri'], 'Toplam alan ∫₀² x² dx = 8/3; yarısı 4/3 olduğundan k³/3 = 4/3 ⇒ k³ = 4 ⇒ k = ∛4 bulunur.'),
  ('Bir yarıçapı 5 cm olan yarım çemberin içine tabanı çap üzerinde olacak şekilde çizilebilecek en büyük alanlı dikdörtgenin alanı kaç cm²\'dir?', '25', ['50 cm² alan', '25√2 cm² alan', '20 cm² alan'], 'Köşe (x, √(25 - x²)) ise A(x) = 2x√(25 - x²); A² = 4(25x² - x⁴) türevinden x² = 25/2; A = 2·(5/√2)·(5/√2) = 25 cm²\'dir.'),
  ('Bir arabanın fren mesafesini modelleyen hız fonksiyonu v(t) = 24 - 6t m/s\'dir. Araç durana kadar kaç metre yol alır?', '48', ['72 metre yol', '36 metre yol', '96 metre yol'], 'Araç v(t) = 0 ⇒ t = 4 saniyede durur; yol ∫₀⁴ (24 - 6t) dt = [24t - 3t²]₀⁴ = 96 - 48 = 48 metredir.'),
  ('İki kez türevlenebilir bir f fonksiyonunun f\'\'(c) = 0 olması x = c noktasının dönüm noktası olması için neden tek başına yeterli değildir?', 'İşaret değişimi zorunludur', ['Birinci türev de sıfır olmalıdır', 'Fonksiyon pozitif değer almalıdır', 'Üçüncü türev negatif kalmalıdır'], 'Örneğin f(x) = x⁴ için f\'\'(0) = 0 olsa da f\'\'(x) = 12x² ≥ 0 işaret değiştirmediğinden x = 0 dönüm noktası değildir.'),
  ('y = x² parabolü üzerindeki bir noktanın A(0, 5/2) noktasına olan uzaklığı en az kaç birimdir?', '3/2', ['5/2', '√2', '9/4'], 'Uzaklık karesi D(x) = x² + (x² - 5/2)² = x⁴ - 4x² + 25/4. D\'(x) = 4x(x² - 2) = 0 ⇒ x² = 2 noktasında D = 4 - 8 + 25/4 = 9/4 ve en kısa uzaklık √(9/4) = 3/2 birimdir.'),
  ('y = x² ve y = 2 - x² parabolleri arasında kalan kapalı bölge x ekseni etrafında 360° döndürülürse oluşan cismin hacmi kaç π birimküptür?', '16/3', ['8/3', '32/15', '32/3'], 'Kesişim x = ±1. [0, 1] üzerinde 2 - x² ≥ x² olduğundan V = 2π ∫₀¹ ((2 - x²)² - (x²)²) dx = 2π ∫₀¹ (4 - 4x²) dx = 2π [4x - 4x³/3]₀¹ = 2π(8/3) = 16π/3 bulunur.'),
  ('Bir dik dairesel koninin içine yerleştirilen en büyük hacimli dik dairesel silindirin yüksekliğinin koninin yüksekliğine oranı kaçtır?', '1/3', ['1/2', '2/3', '1/4'], 'Koni yarıçapı R, yüksekliği H; silindir yarıçapı r, yüksekliği h olsun. Benzerlikten r = R(1 - h/H). V(h) = πR²(1 - h/H)²h ⇒ V\'(h) = 0 ⇒ (1 - h/H)(1 - 3h/H) = 0 ⇒ h/H = 1/3 bulunur.'),
  ('Gerçek sayılarda türevlenebilir f(x) için f(1) = 3 ve f\'(x) grafiği [1, 4] aralığında doğrusal olarak (1, 2) noktasından (4, 8) noktasına çıkıyorsa f(4) kaçtır?', '18', ['15 (f(1) başlangıç değeri unutulmuş)', '21', '12'], 'Temel teoreme göre f(4) - f(1) = ∫₁⁴ f\'(x) dx\'tir. Yamuk alanı ((2 + 8)/2)·(4 - 1) = 15 olduğundan f(4) = 3 + 15 = 18 bulunur.'),
  ('F(x) = ∫₂^(x²) (3t - 1) dt biçiminde tanımlanan F fonksiyonunun x = 2 noktasındaki türevi F\'(2) kaçtır?', '44', ['11', '22', '36'], 'Leibniz/zincir kuralıyla F\'(x) = (3x² - 1) · (2x). x = 2 yazılınca F\'(2) = (12 - 1) · 4 = 44 elde edilir.'),
  ('y = 4x - x² parabolü ile y = mx doğrusu arasında kalan kapalı bölgenin alanı 36 birimkare ise m < 4 için m değeri kaçtır?', '-2', ['2', '-4', '-6'], 'Kesişim x = 0 ve x = 4 - m. Parabol ile doğru arası alan (4 - m)³/6 = 36 ⇒ (4 - m)³ = 216 ⇒ 4 - m = 6 ⇒ m = -2 bulunur.'),
  ('Sabit 20 cm çevreye sahip bir daire diliminin alanı en çok kaç cm² olabilir?', '25', ['50', '20', '100/π'], 'Çevre 2r + s = 20 ⇒ s = 20 - 2r. Dilim alanı A = (1/2)rs = 10r - r². A\'(r) = 10 - 2r = 0 ⇒ r = 5 için A(5) = 50 - 25 = 25 cm² bulunur.'),
  ('x = t² - 2t ve y = t³ - 12t parametrik eğrisinin t = 1 noktasındaki ikinci türevi d²y/dx² kaçtır?', 'Tanımsızdır', ['-3/2', '6', '-9/2'], 'dx/dt = 2t - 2 olduğundan t = 1 anında dx/dt = 0 iken dy/dt = 3t² - 12 = -9 ≠ 0\'dır; eğrinin teğeti düşey olup dy/dx ve d²y/dx² tanımsızdır.'),
  ('Sürekli f(x) fonksiyonu [-3, 3] aralığında tanımlı çift bir fonksiyon ve ∫₀³ f(x) dx = 7 ise ∫₋₃³ (2f(x) + x³ - 1) dx integrali kaçtır?', '22', ['14', '28', '25'], 'Çift fonksiyon olduğundan ∫₋₃³ f(x) dx = 14, tek x³ integrali 0 ve ∫₋₃³ (-1) dx = -6 olur. Sonuç 2(14) + 0 - 6 = 22\'dir.'),
  ('y = x³ eğrisinin üzerindeki A(1, 1) noktasından çizilen teğet, eğriyi başka bir B noktasında kesiyorsa B noktasının apsisi kaçtır?', '-2', ['2', '-1', '-3'], 'y\' = 3x² ⇒ A(1, 1)\'deki teğet y = 3x - 2\'dir. x³ = 3x - 2 ⇒ x³ - 3x + 2 = (x - 1)²(x + 2) = 0 ⇒ B noktasının apsisi x = -2 bulunur.'),
  ('A(0, 3) ve B(6, 5) noktalarının x ekseni üzerindeki bir P(x, 0) noktasına olan uzaklıkları toplamı |PA| + |PB| en küçük olduğunda x kaçtır?', '9/4', ['3', '15/4', '2'], 'B\'nin x eksenine simetriği B\'(6, -5) alınırsa A(0, 3) ile B\'(6, -5) doğrusunun x eksenini kestiği nokta: (x - 0)/3 = (6 - x)/5 ⇒ 5x = 18 - 3x ⇒ x = 9/4 olur.'),
  ('Bir su deposundaki suyun hacmi V(t) = 500(1 - t/20)² litre (0 ≤ t ≤ 20 dakika) formülüyle boşalmaktadır. 10. dakikadaki anlık boşalma hızı kaç litre/dakika olur?', '25', ['50', '125', '10'], 'V\'(t) = 500 · 2(1 - t/20) · (-1/20) = -50(1 - t/20). t = 10 için V\'(10) = -25 L/dk olduğundan boşalma hızı 25 L/dk\'dır.'),
  ('Gerçek sayılarda türevlenebilir f(x) fonksiyonu için f\'(x) daima azalan bir fonksiyon ise f(x) grafiği hakkında aşağıdakilerden hangisi kesinlikle doğrudur?', 'Daima aşağı bükeydir (konkavdır)', ['Daima azalan ve x eksenini keser', 'En az bir yerel minimum noktası vardır', 'Daima yukarı bükeydir (konvekstir)'], 'f\'(x) azalan olduğundan ikinci türev f\'\'(x) ≤ 0 (genellikle negatif) olur; bu da f(x) grafiğinin aşağı bükey (konkav) olduğunu gösterir.'),
  ('Taban açısı 45° olan dik açılı ikizkenar üçgen (V) kesitli 10 metre uzunluğundaki su oluğuna sabit 4 m³/dk hızla su dolmaktadır. Su derinliği 2 metre olduğu anda suyun yükselme hızı kaç m/dk olur?', '1/10', ['1/5', '2/5', '1/20'], 'Derinlik h iken üst genişlik 2h, kesit alanı (2h·h)/2 = h², hacim V = 10h²\'dir. dV/dt = 20h(dh/dt) ⇒ 4 = 20(2)(dh/dt) ⇒ dh/dt = 1/10 m/dk bulunur.'),
  ('y = x² - 2x + 4 parabolüne orijinden çizilen teğetlerin eğimleri çarpımı kaçtır?', '-12', ['12', '-4', '-8'], 'Değme noktası (a, a² - 2a + 4) için (a² - 2a + 4)/a = 2a - 2 ⇒ a² = 4 ⇒ a = ±2. Eğimler f\'(2) = 2 ve f\'(-2) = -6 olup çarpımları 2·(-6) = -12\'dir.'),
  ('y = x² eğrisi ile y = 2x + 3 doğrusunun sınırladığı kapalı bölgeye paralel olan ve eğriye teğet olan doğrunun eğriye değme noktası aşağıdakilerden hangisidir?', '(1, 1)', ['(2, 4)', '(-1, 1)', '(3, 9)'], 'Doğruya paralel teğetin eğimi 2 olmalıdır. y\' = 2x = 2 ⇒ x = 1 ve y = 1² = 1 olup değme noktası (1, 1)\'dir.'),
  ('İki kez türevlenebilir bir f(x) fonksiyonunun grafiği (0, 5) aralığında artan ve aşağı bükey (konkav) ise bu aralıkta f\'(x) ve f\'\'(x) için hangisi doğrudur?', 'f\'(x) > 0 ve f\'\'(x) < 0', ['f\'(x) > 0 ve f\'\'(x) > 0', 'f\'(x) < 0 ve f\'\'(x) < 0', 'f\'(x) < 0 ve f\'\'(x) > 0'], 'Artanlık f\'(x) > 0, aşağı bükeylik (konkavlık) ise f\'\'(x) < 0 koşulunu gerektirir.'),
  ('y = sin(x) eğrisi ile y = cos(x) eğrisi arasında [0, π/4] aralığında kalan bölgenin alanı kaç birimkaredir?', '√2 - 1', ['1 - √2/2 (alt sınır cos(0) eksik)', '√2 + 1', '2 - √2'], '[0, π/4]\'te cos(x) ≥ sin(x). ∫₀^(π/4) (cos(x) - sin(x)) dx = [sin(x) + cos(x)]₀^(π/4) = (√2/2 + √2/2) - (0 + 1) = √2 - 1 bulunur.'),
  ('Bir fabrikanın günlük x birim üretim için marjinal maliyeti M\'(x) = 3x² - 12x + 20 TL ve sabit maliyeti M(0) = 100 TL\'dir. Günlük 4 birim üretim yapıldığında toplam maliyet kaç TL olur?', '148', ['48', '164', '132'], 'M(x) = x³ - 6x² + 20x + 100. x = 4 için M(4) = 64 - 96 + 80 + 100 = 148 TL bulunur.'),
  ('y = x² eğrisinin üzerindeki x = 1 ve x = 2 noktalarını birleştiren kirişe paralel teğetin değme noktasının ordinatı kaçtır?', '9/4', ['3/2', '5/2', '2'], 'Kiriş eğimi (4 - 1)/(2 - 1) = 3. y\' = 2x = 3 ⇒ x = 3/2 ve ordinatı y = (3/2)² = 9/4 olur.'),
  ('Bir telin uzunluğu 40 cm\'dir. Tel iki parçaya bölünüp birinden kare, diğerinden daire yapılacaktır. Toplam alanın en küçük olması için dairenin yarıçapı kaç cm olmalıdır?', '20 / (π + 4)', ['10 / (π + 4) (çevre 2πr yerine πr alınmış)', '40 / (π + 4) (çap uzunluğu bulunmuş)', '20 / (π + 2) (kare çevresi 2a sanılmış)'], 'Daire çevresi 2πr, karenin kenarı (40 - 2πr)/4 = 10 - (π/2)r. Alan A(r) = πr² + (10 - (π/2)r)². A\'(r) = 2πr - π(10 - (π/2)r) = 0 ⇒ r(2 + π/2) = 10 ⇒ r = 20/(π + 4) cm\'dir.'),
  ('y = ln(x² + 1) eğrisine x = 1 apsisli noktasından çizilen normal doğrusunun eğimi kaçtır?', '-1', ['1', '-2', '-1/2'], 'f\'(x) = 2x / (x² + 1) olduğundan x = 1 için teğet eğimi f\'(1) = 2 / 2 = 1 olur. Normal doğrusunun eğimi -1/1 = -1 olarak bulunur.'),
  ('∫₋₂² (x² + 1) / (e^x + 1) dx belirli integralinin simetri dönüşümüyle bulunan değeri kaçtır?', '14/3', ['28/3', '0', '7/3'], 'I = ∫₋₂² f(x) dx integralinde x yerine -x yazılırsa I = ∫₋₂² e^x(x² + 1)/(e^x + 1) dx olur. İkisi toplanırsa 2I = ∫₋₂² (x² + 1) dx = 2[x³/3 + x]₀² = 28/3 ve I = 14/3 bulunur.'),
  ('Yarıçapı 6 cm olan bir dairenin içine çizilebilecek en büyük alanlı dikdörtgenin alanı kaç cm²\'dir?', '72', ['36', '36π', '144'], 'Köşegeni 12 cm olan dikdörtgenin kenarları x ve √(144 - x²) olup alan A(x) = x√(144 - x²) maksimumunu kare olduğunda x = 6√2 için alır; alan (6√2)² = 72 cm²\'dir.'),
  ('f(x) fonksiyonu tüm gerçel sayılarda türevlenebilir olup f(1) = 4 ve her x ∈ [1, 5] için 2 ≤ f\'(x) ≤ 3 koşulunu sağlamaktadır. Ortalama Değer Teoremi\'ne göre f(5) değerinin alabileceği en küçük ve en büyük değerlerin toplamı kaçtır?', '28', ['20 (f(1) değeri iki kez eklenmezse)', '24', '32'], '(f(5) - 4) / (5 - 1) = f\'(c) olduğundan 2 ≤ (f(5) - 4)/4 ≤ 3 ⇒ 8 ≤ f(5) - 4 ≤ 12 ⇒ 12 ≤ f(5) ≤ 16 olur. Toplam 12 + 16 = 28 bulunur.'),
  ('P(x) = x³ + 3x + k polinomunun kaç tane gerçel kökü olduğunu Rolle Teoremi kullanarak inceleyen bir öğrenci kesin olarak hangi sonuca ulaşır?', 'k ne olursa olsun tam bir gerçel kökü vardır', ['k pozitifse hiç gerçel kökü yoktur, negatifse üç kökü vardır', 'k = 0 dışında daima iki farklı gerçel kökü bulunur', 'En az iki, en fazla üç farklı gerçel kökü vardır'], 'P\'(x) = 3x² + 3 > 0 her x için pozitiftir. İki farklı kök olsaydı Rolle Teoremi gereği arada P\'(c) = 0 olmalıydı; çelişki olduğundan tek dereceli polinomun tam 1 gerçel kökü vardır.'),
  ('Bir işletmede üretim düzeyi x₀ iken marjinal gelir R\'(x₀) = 45 TL ve marjinal maliyet C\'(x₀) = 38 TL olarak ölçülmüştür. İşletmenin kısa vadede kârını artırmak için alması gereken en rasyonel karar nedir?', 'Üretim miktarını bir miktar artırmak', ['Üretim miktarını hemen azaltmak', 'Üretimi tamamen durdurup sabit maliyete geçmek', 'Üretim düzeyini değiştirmeyip sabit tutmak'], 'Marjinal kâr P\'(x₀) = R\'(x₀) - C\'(x₀) = 45 - 38 = +7 TL > 0 olduğundan, ek bir birim üretim toplam kârı artıracaktır; bu nedenle üretim artırılmalıdır.'),
  ('Bir otomobil 2 saatte 180 km yol gitmiştir. Aracın konum fonksiyonu sürekli ve türevlenebilir olduğuna göre, Ortalama Değer Teoremi bu yolculuk hakkında hangisini kesin olarak garanti eder?', 'Yolculuk sırasında anlık hızın tam 90 km/sa olduğu en az bir an vardır', ['Araç yolculuk boyunca her an tam 90 km/sa sabit hızla ilerlemiştir', 'Yolculuğun tam 1. saatinde aracın anlık hızı mutlaka 90 km/sa olmuştur', 'Aracın ivmesi yolculuk boyunca hiçbir zaman sıfıra eşit olmamıştır'], 'Ortalama hız (180 - 0)/2 = 90 km/sa olduğundan Ortalama Değer Teoremi gereği s\'(c) = 90 km/sa eşitliğini sağlayan en az bir c ∈ (0, 2) anı mutlaka vardır.'),
  ('lim(x→∞) (1 + 3/x)^(2x) limitinin logaritma ve L\'Hôpital kuralıyla elde edilen değeri aşağıdakilerden hangisidir?', 'e⁶', ['e³', 'e^(3/2)', 'e⁵'], 'ln y = 2x·ln(1 + 3/x) = 2·ln(1 + 3/x)/(1/x). L\'Hôpital ile lim(x→∞) 2·[(-3/x²)/(1 + 3/x)] / (-1/x²) = 6 ⇒ y = e⁶ bulunur.'),
  ('y = √x eğrisine hangi noktasından çizilen normal doğrusu y = -4x + 9 doğrusuna paraleldir?', '(4, 2)', ['(1/16, 1/4)', '(2, √2)', '(16, 4)'], 'Normal eğimi -4 ise teğet eğimi 1/4 olmalıdır. f\'(x) = 1/(2√x) = 1/4 ⇒ √x = 2 ⇒ x = 4 ve y = 2 olup nokta (4, 2) bulunur.'),
  ('f(x) fonksiyonu [0, 4] aralığında sürekli, (0, 4) aralığında türevlenebilir ve f(0) = 2, f(4) = 14\'tür. g(x) = f(x) - 3x fonksiyonu için [0, 4] aralığında Rolle Teoremi uygulandığında kesinlikle elde edilen sonuç nedir?', 'En az bir c ∈ (0, 4) için f\'(c) = 3 olur', ['En az bir c ∈ (0, 4) için f\'(c) = 0 olur', 'Her x ∈ (0, 4) için f\'(x) = 3 sabit olur', 'En az bir c ∈ (0, 4) için f(c) = 3c olur'], 'g(0) = 2 ve g(4) = 14 - 12 = 2 olduğundan Rolle Teoremi gereği en az bir c ∈ (0, 4) için g\'(c) = f\'(c) - 3 = 0 yani f\'(c) = 3 bulunur.'),
  ('lim(n→∞) (1/n) · Σ(k=1\'den n\'e) √(1 + 3k/n) Riemann toplamı limitinin eşiti olan belirli integralin değeri kaçtır?', '14/9', ['7/9', '14/3', '8/3'], 'Toplam ∫₀¹ √(1 + 3x) dx integralidir. u = 1 + 3x için (1/3)∫₁⁴ u^(1/2) du = (1/3)·(2/3)[u^(3/2)]₁⁴ = (2/9)(8 - 1) = 14/9 bulunur.'),
  ('∫₋₁¹ (x² · sin x + e^(|x|)) dx belirli integralinin değeri aşağıdakilerden hangisidir?', '2(e - 1)', ['e - 1', '2e', '0'], 'x²·sin x tek olduğu için integrali 0\'dır. e^(|x|) çift olduğundan 2·∫₀¹ e^x dx = 2(e - 1) elde edilir.'),
  ('∫₀^π (x · sin x) / (1 + cos² x) dx belirli integralinin simetri dönüşümüyle bulunan değeri aşağıdakilerden hangisidir?', 'π²/4', ['π²/2', 'π/4', 'π²/8'], 'u = π - x dönüşümüyle 2I = π·∫₀^π (sin x)/(1 + cos² x) dx olur. t = cos x ile π·∫₋₁¹ 1/(1 + t²) dt = π·(π/4 - (-π/4)) = π²/2 ⇒ I = π²/4 bulunur.'),
  ('Bir bisikletli A noktasından 5 km uzaktaki düz bir sahil yolunun kıyısındaki B noktasına, sahil yolundan 12 km ilerideki C kasabasına en kısa sürede ulaşmak istiyor. Kumda 3 km/sa, yolda 5 km/sa hızla gidebiliyorsa, sahil yoluna B\'den kaç km uzakta çıkmalıdır?', '3,75', ['4', '6', '5'], 'Süre T(x) = √(25 + x²)/3 + (12 - x)/5 olur. T\'(x) = x/(3√(25 + x²)) - 1/5 = 0 ⇒ 5x = 3√(25 + x²) ⇒ 16x² = 225 ⇒ x = 15/4 = 3,75 km bulunur.'),
  ('f(x) fonksiyonu tüm gerçel sayılarda iki kez türevlenebilir ve f(0) = 0, f(2) = 4, f(4) = 0 değerlerini almaktadır. Ortalama Değer Teoremi ve Rolle Teoremi birlikte kullanıldığında aşağıdakilerden hangisi kesinlikle doğrudur?', '(0, 4) aralığında f\'\'(d) < 0 olan en az bir d noktası vardır', ['(0, 4) aralığında her x için f\'\'(x) < 0 koşulu sağlanır', 'x = 2 noktası mutlaka fonksiyonun tek yerel maksimumudur', '(0, 4) aralığında f\'(x) = 0 eşitliği tam iki kez sağlanır'], '[0, 2]\'de f\'(c₁) = 2 ve [2, 4]\'te f\'(c₂) = -2 sağlayan c₁ < c₂ vardır. [c₁, c₂] aralığında f\' için ODT uygulanırsa f\'\'(d) = (-2 - 2)/(c₂ - c₁) < 0 sağlayan d ∈ (0, 4) bulunur.'),
  ('y = e^(-x) eğrisi ile x ekseni, y ekseni ve x = ln 4 doğrusu arasında kalan alan kaç birimkaredir?', '3/4', ['1/4', '4/3', 'ln 4'], 'Alan = ∫₀^(ln 4) e^(-x) dx = [-e^(-x)]₀^(ln 4) = -1/4 - (-1) = 3/4 birimkare bulunur.'),
  ('lim(x→0) ((1 + x)^(1/x) - e) / x limitinin logaritmik açılım veya L\'Hôpital yardımıyla bilinen kesin değeri hangisidir?', '-e/2', ['e/2', '-e', '0'], '(1 + x)^(1/x) = e^(ln(1+x)/x) = e^(1 - x/2 + ...) = e(1 - x/2 + ...) olduğundan lim(x→0) (e(-x/2))/x = -e/2 elde edilir.'),
  ('Bir işletmede x birim üretimde ortalama maliyet AC(x) = C(x)/x minimum değerini alıyorsa, bu üretim noktasında marjinal maliyet C\'(x) ile ortalama maliyet AC(x) arasındaki matematiksel ilişki nedir?', 'C\'(x) = AC(x) eşitliği kesinlikle sağlanır', ['C\'(x) = 0 eşitliği kesinlikle sağlanır', 'C\'(x) = 2·AC(x) eşitliği kesinlikle sağlanır', 'C\'(x) < AC(x) eşitsizliği daima geçerlidir'], 'AC\'(x) = [x·C\'(x) - C(x)] / x² = 0 denkleminden C\'(x) = C(x)/x = AC(x) elde edilir; yani marjinal maliyet eğrisi ortalama maliyet eğrisini tam minimum noktasında keser.'),
  ('y = x³ - x eğrisinin x = 1 noktasındaki normal doğrusunun eğriyi tekrar kesip kesmediğini araştıran bir öğrenci, normalin denklemini hangi biçimde bulur?', 'x + 2y - 1 = 0', ['2x - y - 2 = 0', 'x - 2y - 1 = 0', '2x + y - 2 = 0'], 'x = 1 için y = 0 ve f\'(x) = 3x² - 1 ⇒ f\'(1) = 2\'dir. Normal eğimi -1/2 olup (1, 0) noktasından geçen doğru y = -1/2(x - 1) ⇒ x + 2y - 1 = 0 bulunur.'),
  ('lim(n→∞) (1/n) · Σ(k=1\'den n\'e) (1 / (1 + k/n)) Riemann toplamı limitinin değeri aşağıdakilerden hangisidir?', 'ln 2', ['1/2', '1', 'ln 2 - 1'], 'Bu limit ∫₀¹ 1/(1 + x) dx belirli integraline eşittir; değeri [ln(1 + x)]₀¹ = ln 2 - ln 1 = ln 2 bulunur.'),
  ('Bir şirkette haftalık x birim üretimin toplam maliyeti C(x) = x² + 30x + 400 TL ve satış fiyatı p(x) = 150 - 2x TL ise, kârı maksimize eden üretim düzeyinde toplam kâr kaç TL olur?', '800', ['1200', '20', '1000'], 'P(x) = x(150 - 2x) - (x² + 30x + 400) = -3x² + 120x - 400 olur. P\'(x) = -6x + 120 = 0 ⇒ x = 20 olup P(20) = -1200 + 2400 - 400 = 800 TL bulunur.'),
  ('y = √(16 - x²) yarım çemberine x = 2√2 noktasından çizilen normal doğrusunun denklemi nedir?', 'y = x', ['y = -x + 4√2', 'y = -x', 'y = x + 2√2'], 'Çemberin her noktasındaki normal doğrusu merkezden geçer. Merkez (0, 0) ve değme noktası (2√2, 2√2) olduğundan normal doğrusu y = x\'tir.'),
  ('Sürekli ve türevlenebilir bir f(x) fonksiyonu için f(2) = 5, f(6) = 5 ve f\'\'(x) > 0 her x ∈ (2, 6) için geçerliyse, Rolle Teoremi\'nin garanti ettiği f\'(c) = 0 noktası hakkında hangisi kesinlikle doğrudur?', 'Aralıkta tek bir c noktası vardır ve burada mutlak minimum oluşur', ['Aralıkta tek bir c noktası vardır ve burada mutlak maksimum oluşur', 'Aralıkta en az iki farklı noktada f\'(c) = 0 eşitliği sağlanır', 'c noktası mutlaka aralığın tam ortası olan x = 4 olmak zorundadır'], 'f\'\'(x) > 0 olduğundan f\'(x) kesin artandır; dolayısıyla f\'(c) = 0 en fazla bir kez sağlanır. Rolle gereği en az bir kez sağlandığından tektir ve f\'\'(c) > 0 sebebiyle mutlak minimumdur.'),
  ('∫₋_(π/2)^(π/2) (cos x · sin⁴ x + x³ · cos² x) dx belirli integralinin değeri kaçtır?', '2/5', ['0', '1/5', '4/5'], 'x³·cos² x tek olduğundan integrali 0\'dır. cos x·sin⁴ x çift olduğundan 2·∫₀^(π/2) sin⁴x cos x dx = 2·[sin⁵x/5]₀^(π/2) = 2/5 bulunur.'),
  ('lim(x→0) (ln(1 + 3x) - 3x) / x² limitinin L\'Hôpital kuralıyla bulunan değeri kaçtır?', '-9/2', ['-3/2', '9/2', '-9'], 'İlk L\'Hôpital: (3/(1 + 3x) - 3)/(2x) = (-9x/(1 + 3x))/(2x) = -9 / (2(1 + 3x)). x = 0 için -9/2 bulunur.'),
];
